templates.react:
export function DesignSystem({
  colorToken = "{{colorToken}}",
  radiusToken = {{radiusToken}},
  spacingToken = {{spacingToken}},
  preview = "{{preview}}",
}) {
  return (
    <div role="img" aria-label={`Design system tokens feeding a ${preview} component`} style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box", display: "flex", alignItems: "center", gap: 12 }}>
      <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 11, color: "#24143099" }}><span style={{ display: "inline-block", width: 18, height: 18, background: colorToken, flexShrink: 0 }} />colour</div>
        <div style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 11, color: "#24143099" }}><span style={{ display: "inline-block", width: 18, height: 18, background: "#24143018", borderRadius: radiusToken, flexShrink: 0 }} />radius</div>
        <div style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 11, color: "#24143099" }}><span style={{ display: "inline-block", width: spacingToken, height: 18, background: "#24143018", flexShrink: 0 }} />spacing</div>
      </div>
      <span style={{ fontSize: 18, color: "#24143060" }} aria-hidden="true">&rarr;</span>
      {preview === "button"
        ? <div style={{ flex: 1, textAlign: "center", fontWeight: 600, boxSizing: "border-box", background: colorToken, borderRadius: radiusToken, padding: spacingToken }}>Button</div>
        : <div style={{ flex: 1, textAlign: "center", fontWeight: 600, boxSizing: "border-box", background: "#ffffff", borderRadius: radiusToken, padding: spacingToken, borderTop: `6px solid ${colorToken}` }}>Card</div>}
    </div>
  );
}
